svg.script:
    
    // ==========================================
    // CONFIGURATION VARIABLES
    // ==========================================
    // Fine-tune printer scaling calibration here.
    // 1.0 = Default (Exact 100% scale)
    // 1.01 = Expands ruler markings slightly
    // 0.99 = Shrinks ruler markings slightly
    const SCALING_TUNER = 1.10; 

    // ==========================================
    // CALCULATIONS & GENERATION
    // ==========================================
    
    // 96 DPI conversion: 1 inch = 96 pixels. 1 inch = 2.54 cm.
    // The SCALING_TUNER fine-tunes the physical size of the cm intervals.
    const CM_TO_PX = (96 / 2.54) * SCALING_TUNER;
    
    // Page dimensions in inches converted to pixels
    const pageWidth = 8.5 * 96;
    const pageHeight = 11 * 96;

    // Calculate maximum centimeters that fit on the page area
    const maxCmWidth = Math.floor(pageWidth / CM_TO_PX);
    const maxCmHeight = Math.floor(pageHeight / CM_TO_PX);

    const svgNS = "http://www.w3.org/2000/svg";
    const topGroup = document.getElementById("top-ruler");
    const leftGroup = document.getElementById("left-ruler");

    // --- Helper function to create SVG elements ---
    function createSVGElement(type, attributes) {
        const element = document.createElementNS(svgNS, type);
        for (let key in attributes) {
            element.setAttribute(key, attributes[key]);
        }
        return element;
    }

    // --- Generate Top Ruler ---
    for (let i = 0; i <= maxCmWidth * 10; i++) {
        let cmValue = i / 10;
        let xPosition = cmValue * CM_TO_PX;
        
        if (xPosition > pageWidth) break;

        let tickLength = 5; 
        
        if (i % 10 === 0) {
            tickLength = 15; 
            
            if (i > 0) {
                let text = createSVGElement("text", {
                    "x": xPosition,
                    "y": 26,
                    "class": "ruler-text"
                });
                text.textContent = Math.floor(cmValue);
                topGroup.appendChild(text);
            }
        } else if (i % 5 === 0) {
            tickLength = 10; 
        }

        let line = createSVGElement("line", {
            "x1": xPosition,
            "y1": 0,
            "x2": xPosition,
            "y2": tickLength,
            "class": "ruler-line"
        });
        topGroup.appendChild(line);
    }

    // --- Generate Left Ruler ---
    for (let i = 0; i <= maxCmHeight * 10; i++) {
        let cmValue = i / 10;
        let yPosition = cmValue * CM_TO_PX;

        if (yPosition > pageHeight) break;

        let tickLength = 5;

        if (i % 10 === 0) {
            tickLength = 15;
            
            if (i > 0) {
                let text = createSVGElement("text", {
                    "x": 20,
                    "y": yPosition + 3, 
                    "class": "ruler-text left-text"
                });
                text.textContent = Math.floor(cmValue);
                leftGroup.appendChild(text);
            }
        } else if (i % 5 === 0) {
            tickLength = 10;
        }

        let line = createSVGElement("line", {
            "x1": 0,
            "y1": yPosition,
            "x2": tickLength,
            "y2": yPosition,
            "class": "ruler-line"
        });
        leftGroup.appendChild(line);
    }
